469:   function blockScrollingOnMerchantPage() {
470:     try {
471:       if (isFrameContained) {
472:         return;
473:       }
474: 
475:       // BZ-4625: pin the host viewport while checkout is open. The fixed
476:       // checkout panel is laid out in viewport units; if the page is allowed to
477:       // zoom/scale the panel drifts and leaves a gap. Pinning only during
478:       // checkout keeps pinch-zoom available on the rest of the page.
479:       const viewports = document.querySelectorAll<HTMLMetaElement>('meta[name=viewport]');
480:       if (lockedViewportMetas.size === 0) {
481:         for (const viewport of viewports) {
482:           lockedViewportMetas.set(viewport, viewport.getAttribute('content'));
483:           viewport.setAttribute(
484:             'content',
485:             'width=device-width, initial-scale=1, minimum-scale=1.0, maximum-scale=1.0'
486:           );
487:         }
488:       }
489: 
490:       if (isIOS) {
491:         document.body.style.position = 'fixed';
492:       }
493:       document.body.style.overflow = 'hidden';
494:     } catch (e) {
495:       console.warn('Unable to block scrolling on background page: ', String(e));
496:     }
497:   }
498: 
499:   function removeMerchantPageScrollBlockage() {
500:     try {
501:       // BZ-4625: restore the host viewport so pinch-zoom works again.
502:       for (const [viewport, originalContent] of lockedViewportMetas) {
503:         if (originalContent !== null) {
504:           viewport.setAttribute('content', originalContent);
505:         } else {
506:           viewport.removeAttribute('content');
507:         }
508:       }
509:       lockedViewportMetas.clear();
510: 
511:       if (isIOS) {
512:         document.body.style.position = 'initial';
513:       }
514:       document.body.style.overflow = 'initial';
515:     } catch (e) {
516:       console.error('Error: ', String(e));
517:     }
518:   }
